const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
/* class="note" (not "muted") deliberately -- ".evinfo p.muted" is force-shrunk at narrower widths by the
   shared ".crow .sub,...,.evinfo p.muted,..." !important rule elsewhere in app.css, which was quietly shrinking
   this description paragraph below its own inline font-size on phones while the "Upcoming Yorkseed events" rows
   below it (plain .note divs, not caught by that rule) stayed put -- same inline size here now matches those
   rows exactly, at every width, instead of just at desktop. */
function descHtml(t){if(!t)return "";return String(t).trim().split(/\n\s*\n/).filter(p=>p.trim()).map(p=>`<p class="note" style="margin:0 0 8px;font-size:12.5px;line-height:1.5">${esc(p).replace(/\n/g,"<br>")}</p>`).join("");}
