function tzOff(ms,tz){const p=new Intl.DateTimeFormat("en-US",{timeZone:tz,hourCycle:"h23",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit"}).formatToParts(new Date(ms));const g=t=>+p.find(x=>x.type===t).value;return(Date.UTC(g("year"),g("month")-1,g("day"),g("hour")%24,g("minute"),g("second"))-ms)/6e4;}
function toUtc(date,time,tz){const[y,m,d]=date.split("-").map(Number),[h,mi]=time.split(":").map(Number);const guess=Date.UTC(y,m-1,d,h,mi);let u=guess-tzOff(guess,tz)*6e4;return guess-tzOff(u,tz)*6e4;}
const fT=(ms,tz)=>new Intl.DateTimeFormat("en-US",{timeZone:tz,hour:"numeric",minute:"2-digit"}).format(ms);
const abbr=(ms,tz)=>(new Intl.DateTimeFormat("en-US",{timeZone:tz,timeZoneName:"short"}).formatToParts(ms).find(p=>p.type==="timeZoneName")||{}).value||"";
const dKey=(ms,tz)=>new Intl.DateTimeFormat("en-CA",{timeZone:tz,year:"numeric",month:"2-digit",day:"2-digit"}).format(ms);
const dParts=date=>{const d=new Date(date+"T12:00:00Z");return{mon:new Intl.DateTimeFormat("en-US",{month:"short",timeZone:"UTC"}).format(d),day:d.getUTCDate(),wd:new Intl.DateTimeFormat("en-US",{weekday:"short",timeZone:"UTC"}).format(d),long:new Intl.DateTimeFormat("en-US",{month:"short",day:"numeric",year:"numeric",timeZone:"UTC"}).format(d)}};
const range=(a,b)=>{const A=dParts(a),B=dParts(b);return A.mon===B.mon?`${A.mon} ${A.day}–${B.day}`:`${A.mon} ${A.day} – ${B.mon} ${B.day}`};



// Event listings
function inferType(t){t=t.toLowerCase();
  if(/\bhack|buildathon|ikeathon|harbourhack|build week/.test(t))return"Hackathons";
  if(/demo|showcase|launch night/.test(t))return"Demo Days";
  if(/pitch/.test(t))return"Pitch";
  if(/dinner|lunch|brunch|breakfast|supper|\btable\b/.test(t))return"Communal Dining";
  if(/summit|conference|forum|festival|con\b|agntcon|devfest|sev0|day 2026|innovation day/.test(t))return"Conferences";
  if(/workshop|build day|talk|masterclass|deep dive|for developers|for marketing|for ai engineering|\blabs\b|fireside|panel|bootcamp/.test(t))return"Workshops";
  if(/investor|vc\b|capital|funders|funding|allocator|raise|seed round/.test(t))return"Investor Events";
  return"Meetups";}
function inferTags(t){const T=[];const m=(re,tag)=>{if(re.test(t))T.push(tag)};
  m(/\bai\b|agent|llm|claude|codex|grok|pytorch|inference|openai|elevenlabs|ml\b|rl |manus|genspark|lovable|vibe/i,"AI");
  m(/fintech|financ|payment|crypto|xrpl|money|ramp|stripe/i,"Fintech");
  m(/climate|energy|water|sustainab|nature|esg|microplastic|regenerat|agrifood/i,"Climate");
  m(/health|bio|med|longevity|himss/i,"Health");
  m(/hard tech|deep ?tech|space|nano|rare earth|robot|defense|tough tech/i,"Deep Tech");
  m(/crypto|web3|xrpl|blockchain/i,"Web3");
  m(/investor|\bvc\b|capital|fund|raise|seed|pitch|allocator|funding/i,"Investing");
  m(/founder|startup|entrepreneur/i,"Founders");
  return T.length?T.slice(0,3):["Community"];}
let EVENTS=PULSE.map((p,i)=>{const yk=p.k==="Y";const e={id:"p"+i,title:p.title,hub:p.hub,date:p.date,start:null,end:null,type:yk&&/lunch|\btable\b/i.test(p.title)?"Communal Dining":inferType(p.title),host:yk?(p.title.startsWith("Valois")?"Valois":"Yorkseed"):p.k==="X"?"Yorkseed Expert Series":p.k==="P"?"Yorkseed partner":"",tags:inferTags(p.title),aud:[],place:(yk||p.k==="X")?"spotlight":null,partner:p.k==="P",week:null,img:"ev"+(1+i%8),venue:"",link:p.link,desc:yk?"A Yorkseed event. Apply or RSVP on the event page.":"Time, venue and tickets are on the event page.",fj:1};
  const w=WEEKS.find(w=>w.hub===e.hub&&e.date>=w.start&&e.date<=w.end&&(w.re.test(e.title)||w.re.test(e.link)));if(w)e.week=w.id;return e;});
