  const h=st.hub==="all"?null:hubById(st.hub),w=st.week?weekById(st.week):null;
  {const himg=!h?IMG.cityhero:h.img?IMG[h.img]:"";$("#cityImg").hidden=!himg;if(himg){$("#cityImg").src=himg;$("#cityImg").style.objectPosition=(h&&IMGPOS[h.img])||"50% 50%";}document.querySelector(".cityhero").classList.toggle("plain",!himg);}
