// Which conference has its main days on this date, for the city or week in view
function coreWeek(date){const w=st.week?weekById(st.week):null;if(w&&w.core)return date>=w.core[0]&&date<=w.core[1]?w:null;
  if(st.hub==="all")return null;return WEEKS.find(x=>x.core&&x.hub===st.hub&&date>=x.core[0]&&date<=x.core[1])||null;}
// Before a conference starts, open its week on the first main day (the strip shows the run-up days)
function firstCoreDay(w){return w&&w.core&&addDays(0)<w.core[0]?w.core[0]:null;}
function nextDay(d){const t=new Date(d+"T12:00:00Z");t.setUTCDate(t.getUTCDate()+1);return t.toISOString().slice(0,10);}
function setStripVars(){const nav=document.querySelector(".nav"),el=$("#dStrip"),r=document.documentElement.style;
  r.setProperty("--navh",(nav?nav.offsetHeight:64)+"px");r.setProperty("--dsh",(el&&!el.hidden?el.offsetHeight:0)+"px");}
function renderDayStrip(w){const el=$("#dStrip");if(!el)return;const today=addDays(0);
  st.ignoreDate=true;const pool=filtered();st.ignoreDate=false;
  let days=[];if(w){for(let d=w.start>today?w.start:today;d<=w.end;d=nextDay(d))days.push(d);}else{for(let i=0;i<14;i++)days.push(addDays(i));}
  if(st.day&&!days.includes(st.day))days.push(st.day),days.sort();
  if(days.length<2||!pool.length){el.hidden=true;el.innerHTML="";setStripVars();return;}
  const cnt={};pool.forEach(e=>{cnt[e.date]=(cnt[e.date]||0)+1});
  el.hidden=false;
  el.innerHTML=`<button type="button" class="dsall" data-dsday="" aria-pressed="${!st.day}" aria-label="All days, ${pool.length} events"><small>All</small><b>Days</b><span>${pool.length}</span></button>`+days.map(d=>{const p=dParts(d),cw=coreWeek(d),n=cnt[d]||0;
    return`<button type="button" class="${cw?"core":""}${n?"":" none"}" data-dsday="${d}" aria-pressed="${st.day===d}" aria-label="${p.wd} ${p.day} ${p.mon}, ${n} event${n===1?"":"s"}${cw?", "+esc(cw.coreName||cw.name)+" day":""}"><small>${d===today?"Today":p.wd}</small><b>${p.day}</b><span>${n}</span></button>`}).join("");
  const on=el.querySelector('[aria-pressed="true"]');if(on&&on.dataset.dsday)el.scrollLeft=Math.max(0,on.offsetLeft-el.clientWidth/2+on.offsetWidth/2);
  setStripVars();}
function renderCal(h,w){
  st.ignoreDate=true;const all=filtered();st.ignoreDate=false;
  if(!st.month){const f=(w?w.start:addDays(0));st.month=f.slice(0,7);}
  const [y,m]=st.month.split("-").map(Number);const first=Date.UTC(y,m-1,1),dim=new Date(Date.UTC(y,m,0)).getUTCDate(),off=(new Date(first).getUTCDay()+6)%7;
  const by={};all.forEach(e=>{(by[e.date]=by[e.date]||[]).push(e)});
  const inMonth=all.filter(e=>e.date.slice(0,7)===st.month).length,today=addDays(0);
  $("#listCount").innerHTML=`${inMonth} <em>event${inMonth===1?"":"s"}</em> ${w?(addDays(0)>=w.start&&addDays(0)<=w.end?"this week":"at "+esc(w.name)+", "+range(w.start,w.end)):h?"in "+h.name:"worldwide"}`;
  $("#spot").innerHTML="";$("#moreWrap").innerHTML="";
  const mName=new Intl.DateTimeFormat("en-US",{month:"long",timeZone:"UTC"}).format(first);
  let cells=["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(d=>`<div class="dow">${d}</div>`).join("");
  const cur=st.month===today.slice(0,7);let s0=0;if(cur){const td=+today.slice(8);s0=Math.floor((off+td-1)/7)*7;}
  const total=Math.ceil((off+dim)/7)*7;
  for(let i=s0;i<total;i++){const dt=new Date(first+(i-off)*864e5).toISOString().slice(0,10),out=dt.slice(0,7)!==st.month,evs=(by[dt]||[]).sort((a,b)=>((RANK[a.place]??9)-(RANK[b.place]??9))||a.utc-b.utc);
    const cls=["cday",out?"out":"",dt===today?"today":"",dt<today?"past":""].join(" ");
    cells+=`<div class="${cls}"><button class="dn" type="button" data-day="${dt}" aria-label="${dt}: ${evs.length} events">${+dt.slice(8)}${evs.length?`<small>${evs.length}</small>`:""}</button>${out?"":evs.slice(0,4).map(e=>`<button class="cev${e.place?" hl":""}" type="button" data-ev="${e.id}" title="${esc(e.title)}"><b>${fE(e,hubById(e.hub).tz).replace(/ (AM|PM)/,m=>m.trim()==="AM"?"a":"p")}</b>${esc(e.title)}</button>`).join("")+(evs.length>4?`<button class="cmore" type="button" data-day="${dt}">+${evs.length-4} more</button>`:"")}</div>`;}
  $("#rows").innerHTML=`<div class="calhead"><h3>${mName} <em>${y}</em></h3><div class="nav2"><span>${inMonth} event${inMonth===1?"":"s"}</span><button type="button" data-mon="-1" aria-label="Previous month">‹</button><button type="button" data-mon="1" aria-label="Next month">›</button></div></div><div class="cal">${cells}</div>`;
}
function ysThumb(e){return evImgTag(e,IMG[e.img]).replace("<img ",'<img style="width:100%;height:100%;object-fit:cover;display:block" ');}
function ysUpcomingHtml(excludeId){const YS_HOSTS=["Yorkseed","Valois","Yorkseed Expert Series"];const list=upcoming().filter(x=>YS_HOSTS.includes(x.host)&&x.id!==excludeId).sort((a,b)=>(a.date+(a.start||"99")).localeCompare(b.date+(b.start||"99"))).slice(0,8);if(!list.length)return "";
  return `<div style="margin-top:10px"><b>Upcoming Yorkseed events</b><div style="margin-top:4px">${list.map(x=>{const hh=hubById(x.hub),dd=dParts(x.date);const loc=(hh.country&&hh.id!=="virtual")?`${hh.name}, ${hh.country}`:hh.name;return `<a href="#" data-ev="${x.id}" style="display:flex;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line);text-decoration:none;color:inherit"><span style="flex:none;width:56px;height:56px;overflow:hidden;border-radius:4px;background:var(--line)">${ysThumb(x)}</span><span style="min-width:0"><b style="font-size:14px">${esc(x.title)}</b><div class="note" style="font-size:12.5px;margin-top:2px">${dd.long} · ${esc(loc)}</div></span></a>`;}).join("")}</div></div>`;}
