const TZ_ALIAS={"America/Detroit":"nyc","America/Indiana/Indianapolis":"nyc","America/Kentucky/Louisville":"nyc","America/Phoenix":"la","America/Denver":"atx","America/Vancouver":"sf","America/Halifax":"mtl","Europe/Brussels":"ams","Europe/Vienna":"muc","Europe/Prague":"ber","Europe/Warsaw":"ber","Europe/Oslo":"sto","Europe/Athens":"hel","Asia/Riyadh":"dxb","Asia/Qatar":"dxb","Asia/Shanghai":"hkg","Asia/Taipei":"tpe","Asia/Jakarta":"sgp","Asia/Manila":"sgp","Asia/Bangkok":"kul","Australia/Melbourne":"syd","Australia/Brisbane":"syd","America/Santiago":"bue","America/Bogota":"mex","America/Lima":"mex","Asia/Calcutta":"blr","America/Buenos_Aires":"bue","Asia/Tel_Aviv":"tlv","America/Montreal":"mtl","Asia/Saigon":"sgp","Asia/Ho_Chi_Minh":"sgp"};
function guessHome(){const n=id=>upcoming().filter(e=>e.hub===id).length;const same=HUBS.filter(h=>h.tz===myTz&&h.id!=="virtual").sort((a,b)=>n(b.id)-n(a.id));if(same.length)return{id:same[0].id,how:"tz"};if(TZ_ALIAS[myTz])return{id:TZ_ALIAS[myTz],how:"tz"};return{id:"all",how:"tz"};}
