// event
// Every outbound registration link carries a Yorkseed referral
const YS_INBOX="info@yorkseed.co";
/* Submissions go to the Yorkseed backend as "pending". The team gets an email and approves them in the Event Manager. */
const SUB_API="https://yorkseed-backend-production.up.railway.app/api/list-submissions";
/* Self-serve sidebar ads: upload + pay by Stripe Checkout, live as soon as paid, gone when the run ends. */
const ADS_API="https://yorkseed-backend-production.up.railway.app/api/list-ads";
let SELF_ADS=[];
/* count each ad's views (once per page load, when at least half of it is on screen) and clicks */
const AD_SEEN=new Set();const adHit=(id,t)=>{try{navigator.sendBeacon(ADS_API+"/hit/"+id+"/"+t);}catch(e){}};
const AD_IO="IntersectionObserver" in window?new IntersectionObserver(es=>es.forEach(en=>{const id=en.target.dataset.adid;if(en.isIntersecting&&id&&!AD_SEEN.has(id)){AD_SEEN.add(id);adHit(id,"v");}}),{threshold:.5}):null;
function watchAds(root){if(!root)return;root.querySelectorAll("[data-adid]").forEach(el=>{if(AD_IO&&!el._w){el._w=1;AD_IO.observe(el);}if(!el._c){el._c=1;el.addEventListener("click",()=>adHit(el.dataset.adid,"c"));}});}
function loadSelfAds(){return fetch(ADS_API+"/live").then(r=>r.ok?r.json():{ads:[]}).then(x=>{SELF_ADS=((x&&x.ads)||[]).map(a=>({adId:a.id,kind:a.kind||"side",hub:a.hub,brand:a.brand,headline:a.alt||"",url:a.url,img:a.img,start:a.start,end:a.end,live:true,self:true}));if(typeof rerenderAll==="function")rerenderAll();}).catch(()=>{});}
async function sendSubmission(p){try{const ctl=new AbortController();const t=setTimeout(()=>ctl.abort(),12000);
  const r=await fetch(SUB_API+"/submit",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p),signal:ctl.signal});clearTimeout(t);
  const x=await r.json().catch(()=>({}));return r.ok?{ok:true,dup:!!x.duplicate,live:!!x.approved}:{ok:false,msg:x.message||""};}catch(e){return{ok:false,msg:""};}}
const okEmail=v=>/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v||"");
/* optional cover image on submissions: shrunk in the browser to at most 1600px and ~900 KB of JPEG, then sent with the event */
const COVER={s:"",c:""};
function shrinkCover(file){return new Promise((ok,no)=>{
  if(!file||!/^image\/(jpeg|png|webp|gif|heic|heif|avif)$/i.test(file.type||""))return no("Pick a JPG, PNG or WebP image.");
  if(file.size>25*1024*1024)return no("That image is over 25 MB. Please pick a smaller one.");
  const u=URL.createObjectURL(file),im=new Image();
  im.onload=()=>{URL.revokeObjectURL(u);const w0=im.naturalWidth,h0=im.naturalHeight;
    if(w0<400||h0<200)return no(`That image is only ${w0} × ${h0}. Use one at least 1200 × 630 so it looks sharp.`);
    let s=Math.min(1,1600/w0,1600/h0),out="";
    for(let i=0;i<6;i++){const cv=document.createElement("canvas");cv.width=Math.round(w0*s);cv.height=Math.round(h0*s);const g=cv.getContext("2d");g.fillStyle="#fff";g.fillRect(0,0,cv.width,cv.height);g.drawImage(im,0,0,cv.width,cv.height);
      out=cv.toDataURL("image/jpeg",i<3?0.86-i*0.1:0.7);if(out.length*0.75<900*1024)break;s*=0.8;}
    out.length*0.75<1.1*1024*1024?ok(out):no("We couldn't shrink that image enough. Try a smaller one.");};
  im.onerror=()=>{URL.revokeObjectURL(u);no("We couldn't read that image. Try a JPG or PNG.");};im.src=u;});}
/* shrink any image in the browser: longest side <= maxPx, JPEG under maxBytes; rejects images narrower than minW */
function shrinkTo(file,maxPx,maxBytes,minW){return new Promise((ok,no)=>{
  if(!file||!/^image\/(jpeg|png|webp|gif)$/i.test(file.type||""))return no("Pick a JPG or PNG image.");
  if(file.size>25*1024*1024)return no("That image is over 25 MB. Please pick a smaller one.");
  const u=URL.createObjectURL(file),im=new Image();
  im.onload=()=>{URL.revokeObjectURL(u);const w0=im.naturalWidth,h0=im.naturalHeight;
    if(w0<minW)return no(`That image is only ${w0} px wide. Please use one at least ${minW} px wide.`);
    let sc=Math.min(1,maxPx/w0,maxPx/h0),out="",w=w0,h=h0;
    for(let i=0;i<7;i++){w=Math.round(w0*sc);h=Math.round(h0*sc);const cv=document.createElement("canvas");cv.width=w;cv.height=h;const g=cv.getContext("2d");g.fillStyle="#fff";g.fillRect(0,0,w,h);g.drawImage(im,0,0,w,h);
      out=cv.toDataURL("image/jpeg",i<3?0.86-i*0.1:0.6);if(out.length*0.75<maxBytes)break;sc*=0.8;}
    out.length*0.75<maxBytes*1.2?ok({url:out,w,h}):no("We couldn't shrink that image enough. Try a smaller one.");};
  im.onerror=()=>{URL.revokeObjectURL(u);no("We couldn't read that image. Try a JPG or PNG.");};im.src=u;});}
function mountCover(box,key,id){if(!box)return;
  const draw=(msg)=>{const v=COVER[key];box.innerHTML=`<input type="file" id="${id}" accept="image/jpeg,image/png,image/webp,image/heic,image/heif"><label class="cvbtn" for="${id}" aria-label="${v?"Change cover image":"Upload a cover image"}">${v?`<img src="${v}" alt="">`:"+ Upload"}</label><span class="cvside">${msg?`<span style="color:var(--red,#b42318)">${esc(msg)}</span>`:v?"Looks good. This shows on your event card.":"Landscape works best, about 1200 × 630. JPG or PNG."}${v?`<button type="button" data-cvrm>Remove</button>`:""}</span>`;
    box.querySelector("input").onchange=async ev=>{const f=ev.target.files&&ev.target.files[0];if(!f)return;box.querySelector(".cvside").textContent="Preparing…";try{COVER[key]=await shrinkCover(f);draw();}catch(m){COVER[key]="";draw(typeof m==="string"?m:"We couldn't read that image.");}};
    const rm=box.querySelector("[data-cvrm]");if(rm)rm.onclick=()=>{COVER[key]="";draw();};};
  draw();}
mountCover(document.querySelector('[data-cover="s"]'),"s","sCover");
function mailYS(subject,lines){return "mailto:"+YS_INBOX+"?subject="+encodeURIComponent(subject)+"&body="+encodeURIComponent(lines.filter(x=>x!==null&&x!=="").join("\n"));}
function refLink(u,camp){try{const x=new URL(u);x.searchParams.set("utm_source","yorkseed");x.searchParams.set("utm_medium","the_list");if(camp)x.searchParams.set("utm_campaign",camp);if(/(^|\.)lu\.?ma(\.com)?$/.test(x.hostname)||/luma\.com$/.test(x.hostname))x.searchParams.set("ref","yorkseed");return x.toString();}catch(e){return u;}}
function placeText(e,h){let v=(e.venue||"").replace(/\s*•\s*/g," · ").replace(new RegExp("^"+h.name.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+"\\s*[,·]\\s*(Portugal|USA|United States)?\\s*[·,]?\\s*","i"),"").trim();const city=(!v&&h.country&&h.id!=="virtual")?`${h.name}, ${h.country}`:h.name;return [city,v].filter(Boolean).join(" · ");}
function renderEvent(){
  const e=EVENTS.find(x=>x.id===st.evId);if(!e){show("home");return;}
  const h=hubById(e.hub),d=dParts(e.date),wk=e.week?weekById(e.week):null;
  const initials=e.host.split(/\s+/).map(w=>w[0]).join("").slice(0,2).toUpperCase();
  $("#evPage").innerHTML=`<div class="evimg">${evImgTag(e,e.hub==="nyc"&&e.place?IMG.detail:IMG[{ev5:"ev1",ev6:"ev4",ev7:"ev3",ev8:"ev2"}[e.img]||e.img])}<div class="dblk">${d.mon}<b>${d.day}</b>${d.wd}</div></div>
  <div class="evinfo">
    <div style="display:flex;justify-content:space-between;gap:12px;align-items:start"><h1>${esc(e.title)}</h1><span>${badge(e.place)}${hsBadge(e)}</span></div>
    <div class="meta">${ico("clock")}${e.noTime?"Time on the event page":fE(e,h.tz)+(e.end?" – "+fEnd(e,h.tz):"")+" "+abE(e,h.tz)}</div>
    <div class="meta">${ico("pin")}<span>${esc(placeText(e,h))}${wk?" · "+esc(wk.name):""}</span></div>
    <div class="meta" style="gap:14px">${e.price?`<span class="badge" style="border:1px solid var(--line);color:var(--ink)">${esc(e.price)}</span>`:""}${(e.aud||[]).map(a=>`<span class="eyebrow" style="color:var(--accent);font-size:10.5px">${esc(a)}</span>`).join("")}${e.series?`<em>${esc(e.series)}</em>`:""}</div>
    ${e.host?`<div class="host"><div class="who"><span class="av">${esc(initials)}</span><span><small>Hosted by</small><b>${esc(e.host)}</b></span></div><button class="btn btn-sm btn-primary" type="button" id="follow">Follow</button></div>`:""}
    <div class="tags">${e.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join("")}<span class="tag">${esc(e.type)}</span>${(e.cats||[]).filter(c=>c!==e.type).map(c=>`<span class="tag">${esc(c)}</span>`).join("")}</div>
    ${descHtml(e.desc)}
    ${e.noTime?"":`<div class="timebox"><span>Local</span>${new Intl.DateTimeFormat("en-US",{weekday:"short",month:"short",day:"numeric",timeZone:h.tz}).format(e.utc)}, ${fE(e,h.tz)} ${abE(e,h.tz)}<span>Your time</span>${new Intl.DateTimeFormat("en-US",{weekday:"short",month:"short",day:"numeric",hour:"numeric",minute:"2-digit",timeZone:myTz,timeZoneName:"short"}).format(e.utc)}</div>`}
    ${e.link?`<a class="btn btn-primary" href="${esc(refLink(e.link,h.id))}" target="_blank" rel="noopener">Register ${ico("ext")}</a>`:`<button class="btn btn-primary" type="button" id="regBtn">Register ${ico("ext")}</button>`}
    <div class="two"><button class="btn btn-line" type="button" id="calBtn">${ico("cal")}Add to Calendar</button><button class="btn btn-line" type="button" id="shareBtn">${ico("share")}Share</button></div>
    <div><b>Location</b><div class="note" style="font-size:14px">${esc(placeText(e,h))}</div>${/after (rsvp|registration|approval)/i.test(e.venue||"")?"":`<div class="note">Exact address provided after registration</div>`}</div>
    <div class="map" aria-hidden="true">${mapSvg(e.id)}</div>
    ${bannerHtml("event",e.hub,null,true)}
    <p class="note" style="font-size:13px;margin:0">Hosting this event? <a href="#" data-ys-change data-title="${esc(e.title)}" data-date="${esc(e.date||"")}" data-link="${esc(e.link||"")}" style="color:var(--accent)">Change or remove it</a></p>
    ${cityUpcomingHtml(e.hub,e.id)}
    ${ysUpcomingHtml(e.id)}
  </div>`;
  {const w2=e.week?weekById(e.week):null;if(w2&&w2.ys)$("#evPage").insertAdjacentHTML("beforeend",`<div class="evys">${ysProgramsHtml(w2)}</div>`);}
  $("#evPage").insertAdjacentHTML("beforeend",sponsorsHtml());
  if($("#follow"))$("#follow").onclick=ev=>{ev.target.textContent=ev.target.textContent==="Follow"?"Following":"Follow";};
  const rb=$("#regBtn");if(rb)rb.onclick=()=>toast("Sample event: real listings link to the organizer's registration page.");
  $("#calBtn").onclick=ev=>calMenu(e,ev.currentTarget);
  $("#shareBtn").onclick=ev=>shareEv(e,ev.currentTarget);
}
function mapSvg(seed){let s=[...seed].reduce((a,c)=>a+c.charCodeAt(0),7);const r=()=>(s=(s*9301+49297)%233280)/233280;let l="";for(let i=0;i<9;i++){const y=12+i*12+r()*4;l+=`<path d="M0 ${y} L400 ${y+r()*14-7}" stroke="var(--line)" stroke-width="${r()>.75?4:1.5}"/>`;}for(let i=0;i<14;i++){const x=10+i*30+r()*8;l+=`<path d="M${x} 0 L${x+r()*30-15} 120" stroke="var(--line)" stroke-width="${r()>.8?4:1.5}"/>`;}return`<svg viewBox="0 0 400 120"><rect width="400" height="120" fill="var(--bg-2)"/>${l}<path d="M330 0 C310 40 350 80 320 120" stroke="var(--accent-soft)" stroke-width="14" fill="none"/><g transform="translate(200 52)"><path d="M0 18 C-9 6 -10 2 -10 -2 a10 10 0 0 1 20 0 c0 4 -1 8 -10 20z" fill="#E5484D"/><circle cy="-2" r="3.5" fill="#fff"/></g></svg>`;}

// ---------- submit wizard ----------
let step=1;
function paneShow(){
  document.querySelectorAll("[data-pane]").forEach(p=>p.hidden=+p.dataset.pane!==step);
  document.querySelectorAll(".step").forEach(s=>s.classList.toggle("on",+s.dataset.s<=step));
  $("#prevBtn").hidden=step===1;
  const tot=total();
  $("#nextBtn").textContent=step<4?"Continue":"Submit Event";
  if(step===4)renderReview();
}
function total(){const p=document.querySelector("input[name=place]:checked").value;return TIERS.find(t=>t.id===p).price+($("#sNews").checked?79:0);}
function updSum(){paneShow();}
function err(id,m){const e=$(id);e.textContent=m;e.hidden=!m;return !m;}
function validate(){
  if(step===1){const a=err("#eTitle",$("#sTitle").value.trim()?"":"Add a title so people know what it is."),b=err("#eDesc",$("#sDesc").value.trim()?"":"Add a short description."),c=err("#eHost",$("#sHost").value.trim()?"":"Add who is hosting."),d=err("#eEmail",okEmail($("#sEmail").value.trim())?"":"Add your email so we can confirm your event.");return a&&b&&c&&d;}
  if(step===2)return err("#eDate",$("#sDate").value?"":"Pick the date in the event's local time.");
  if(step===3){const p=document.querySelector("input[name=place]:checked").value;if(p==="week"&&!$("#sWeek").value){toast("A Conference Week Pin needs a week. Go back to Date & Location to pick one.");return false;}}
  return true;
}
function renderReview(){
  const p=TIERS.find(t=>t.id===document.querySelector("input[name=place]:checked").value);const h=hubById($("#sHub").value);const w=$("#sWeek").value?weekById($("#sWeek").value):null;
  $("#review").innerHTML=`<dt>Event</dt><dd>${esc($("#sTitle").value)}</dd><dt>Type</dt><dd>${esc([$("#sType").value,...picked("sSectors"),...picked("sCats")].filter(Boolean).join(" · "))}</dd><dt>Host</dt><dd>${esc($("#sHost").value)}</dd><dt>When</dt><dd>${esc($("#sDate").value)} · ${esc($("#sStart").value)}–${esc($("#sEnd").value)} ${h.name} time</dd><dt>City</dt><dd>${h.name}${w?" · "+esc(w.name):""}</dd>`;
}
function syncWeeks(){const ws=WEEKS.filter(w=>w.hub===$("#sHub").value);$("#sWeek").innerHTML='<option value="">No</option>'+ws.map(w=>`<option value="${w.id}">${esc(w.name)} (${range(w.start,w.end)})</option>`).join("");}
function setPlace(id){const r=document.querySelector(`input[name=place][value="${id}"]`);if(r){r.checked=true;updSum();}}
$("#subForm").addEventListener("submit",async ev=>{
  ev.preventDefault();if(!validate())return;
  if(step<4){step=step===2?4:step+1;paneShow();return;}
  const place=document.querySelector("input[name=place]:checked").value;
  const e=decorate({id:"u"+Date.now(),title:$("#sTitle").value.trim(),hub:$("#sHub").value,date:$("#sDate").value,start:$("#sStart").value||"18:00",end:$("#sEnd").value||"21:00",type:$("#sType").value,xsectors:picked("sSectors"),xcats:picked("sCats"),host:$("#sHost").value.trim(),tags:[$("#sType").value.replace(/s$/,"")],place:place==="free"?null:place,week:$("#sWeek").value||null,img:"ev"+(1+Math.floor(Math.random()*8)),venue:$("#sVenue").value.trim(),link:/^https?:\/\//.test($("#sLink").value)?$("#sLink").value:"",desc:$("#sDesc").value.trim(),cover:COVER.s||"",mine:true});
  EVENTS.push(e);
  try{const s=JSON.parse(localStorage.getItem("yl-subs2")||"[]");const c={...e};delete c.utc;delete c.utcEnd;delete c.cover;s.push(c);localStorage.setItem("yl-subs2",JSON.stringify(s));}catch(x){}
  const paid=place!=="free";
  const nb=$("#nextBtn");nb.disabled=true;nb.textContent="Sending…";
  const res=await sendSubmission({title:e.title,hub:e.hub,hubName:hubById(e.hub).name,date:e.date,start:e.start,end:e.end,tz:hubById(e.hub).tz,venue:e.venue,type:e.type,sector:(e.xsectors||[]).join(","),tags:(e.xcats||[]).join(","),host:e.host,link:e.link,desc:e.desc,week:e.week||"",placement:place,name:$("#sName").value.trim(),email:$("#sEmail").value.trim(),website:$("#sWebsite").value,image:COVER.s||"",via:"form"});
  nb.disabled=false;nb.textContent="Continue";
  if(!res.ok){EVENTS.pop();toast(res.msg||`We couldn't send that just now. Please try again, or email ${YS_INBOX}.`);return;}
  $("#subForm").reset();COVER.s="";mountCover(document.querySelector('[data-cover="s"]'),"s","sCover");$("#sStart").value="18:30";$("#sEnd").value="21:00";syncWeeks();setPlace("free");step=1;paneShow();
  renderHome();st.hub=e.hub;st.type="all";st.topic=null;st.q="";st.ysOnly=false;st.week=null;st.date="any";goCity();
  toast(res.dup?"We already have this event. We'll be in touch if anything is missing.":res.live?"Thanks. Your event is live on the List now.":"Received. We review every event within a day, and it goes live on the List once approved. You can preview it here in the meantime.");
});
$("#prevBtn").onclick=()=>{if(step>1){step=step===4?2:step-1;paneShow();}};

// ---------- events ----------
function scrollToId(id){if(st.view!=="home"&&!["submit","pricing","partner"].includes(id))show("home");requestAnimationFrame(()=>document.getElementById(id).scrollIntoView({behavior:"smooth",block:"start"}));}
document.addEventListener("click",ev=>{
  const t=ev.target.closest("button,article,[data-ev],.hubdot,a[data-city],a[data-weekgo],a[data-go]");if(!t)return;
  if(t.tagName==="A")ev.preventDefault();
  if(t.dataset.chat){openChat();return;}
  if(t.dataset.promo){let f=$("#footEmail");if(f&&f.offsetParent===null){show("home");f=$("#footEmail");}if(f){f.scrollIntoView({behavior:"smooth",block:"center"});setTimeout(()=>f.focus({preventScroll:true}),450);}return;}
  if(t.dataset.book){openBook(t.dataset.book,t.dataset.bcity);return;}
  if(t.dataset.reg){fitRegion(t.dataset.reg);return;}
  if(t.classList&&t.classList.contains("hubdot"))return;
  if(t.dataset.save){ev.stopPropagation();const id=t.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem("yl-saved",JSON.stringify([...saved]))}catch(x){}document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>b.setAttribute("aria-pressed",String(saved.has(id))));toast(saved.has(id)?"Saved. Find it under Saved in the menu.":"Removed from saved.");updSavedN();if(st.savedOnly&&st.view==="city")renderCity();return;}
  if(t.dataset.ev){goEvent(t.dataset.ev);return;}
  if(t.dataset.go==="home"){show("home");return;}
  if(t.dataset.go==="city"){st.week=null;st.topic=null;st.q="";st.ysOnly=false;st.date="any";st.type="all";goCity(t.dataset.hub);return;}
  if(t.dataset.scroll){scrollToId(t.dataset.scroll);return;}
  if(t.dataset.city){st.week=null;st.topic=null;st.q="";st.ysOnly=false;st.date="any";goCity(t.dataset.city);return;}
  if(t.dataset.topic){st.topic=t.dataset.topic;st.week=null;st.q="";st.ysOnly=false;goCity("all");return;}
  if(t.dataset.weekgo){st.week=t.dataset.weekgo;st.topic=null;st.q="";st.ysOnly=false;st.date="any";st.type="all";goCity(weekById(st.week).hub);{const fd=firstCoreDay(weekById(st.week));if(fd){st.day=fd;st.mode="list";renderCity();}}return;}
  if(t.dataset.pin){openChat();return;const w=weekById(t.dataset.pin);$("#sHub").value=w.hub;syncWeeks();$("#sWeek").value=w.id;$("#sDate").value=w.start;scrollToId("submit");toast(`Add your side event for ${w.name}. The week is already selected.`);return;}
  if(t.dataset.tier){setPlace(t.dataset.tier);step=1;paneShow();scrollToId("submit");return;}
  if(t.dataset.tab){st.hub=t.dataset.tab;if(st.week&&weekById(st.week).hub!==st.hub)st.week=null;renderCity();return;}
  if(t.dataset.type){st.type=t.dataset.type;renderCity();return;}
  if(t.dataset.sector){st.topic=st.topic===t.dataset.sector?null:t.dataset.sector;renderCity();return;}
  if(t.dataset.date){st.date=t.dataset.date;st.day=null;renderCity();return;}
  if(t.dataset.v){st.mode=t.dataset.v;renderCity();return;}
  if(t.dataset.day){st.day=t.dataset.day;st.mode="list";st.date="any";renderCity();document.getElementById("cq").scrollIntoView({behavior:"smooth",block:"center"});return;}
  if(t.dataset.mon){const [y,m]=st.month.split("-").map(Number);const d=new Date(Date.UTC(y,m-1+(+t.dataset.mon),1));st.month=d.toISOString().slice(0,7);renderCity();return;}
  if(t.dataset.host){st.q=t.dataset.host;renderCity();return;}
  if(t.dataset.ysfilter){st.ysOnly=true;st.week=null;st.q="";st.type="all";st.topic=null;st.date="any";goCity("all");document.getElementById("cq").scrollIntoView({behavior:"smooth",block:"center"});return;}
  if(t.dataset.more){st.limit+=PAGE;renderCity();return;}
  if(t.dataset.clear){if(t.dataset.clear==="date")st.date="any";else if(t.dataset.clear==="day")st.day=null;else if(t.dataset.clear==="savedOnly")st.savedOnly=false;else if(t.dataset.clear==="ysfilter")st.ysOnly=false;else st[t.dataset.clear]=t.dataset.clear==="q"?"":null;renderCity();return;}
});
document.addEventListener("keydown",ev=>{if(ev.key==="Enter"&&ev.target.matches("article[data-ev]"))goEvent(ev.target.dataset.ev);if(ev.key==="Escape")$("#modal").hidden=true;});
$("#cityShare").onclick=shareList;
$("#backBtn").onclick=()=>{if(NAV_DEPTH>0)history.back();else show(st.prev==="event"?"home":st.prev);};
