{const mb=$("#menuBtn"),mn=$("#mnav");const setM=o=>{mn.hidden=!o;mb.setAttribute("aria-expanded",String(o));mb.classList.toggle("on",o);};mb.onclick=()=>setM(mn.hidden);mn.addEventListener("click",e=>{if(e.target.closest("button,a"))setM(false);});addEventListener("resize",()=>{if(innerWidth>980)setM(false);});}
$("#homeSel").onchange=e=>{const v=e.target.value;setHome(v);st.q="";st.ysOnly=false;st.date="any";st.topic=null;st.week=null;st.type="all";goCity(v);};
$("#hHub").onchange=e=>{st.q=$("#hq").value.trim();st.ysOnly=false;st.date="any";st.topic=null;st.week=null;st.type="all";goCity(e.target.value);e.target.value="all";};
$("#upElse").onclick=()=>setHome("all");
$("#railLink").addEventListener("submit",e=>{e.preventDefault();const v=$("#railLinkIn").value.trim();$("#railLinkIn").value="";openChat(v||undefined);});
$("#cq").addEventListener("input",e=>{st.q=e.target.value;renderCity();});
$("#footSub").addEventListener("submit",e=>{e.preventDefault();const v=$("#footEmail").value.trim();if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)){toast("Enter an email address like you@company.com.");return;}$("#footEmail").value="";pulseSub(v);});
$("#cityForm").addEventListener("submit",e=>{e.preventDefault();const v=$("#cEmail").value.trim();if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)){toast("Enter an email address like you@company.com.");return;}$("#cEmail").value="";pulseSub(v,st.hub);});
function pulseSub(email,hub){const u=new URL("https://pulse.yorkseed.co/subscribe");u.searchParams.set("email",email);u.searchParams.set("utm_source","yorkseed");u.searchParams.set("utm_medium","the_list");u.searchParams.set("utm_campaign","subscribe"+(hub&&hub!=="all"?"_"+hub:""));window.open(u.toString(),"_blank","noopener");toast("Opening Yorkseed Pulse to confirm your subscription.");}
$("#moreWeeks").onclick=()=>{st.allWeeks=!st.allWeeks;renderWeeks();};
