function promoFor(pref,i){const t=addDays(0);const ps=PROMOS.filter(p=>!p.until||p.until>=t);const pl=Array.isArray(pref)?pref:[pref];for(const id of pl){const f=ps.find(p=>p.id===id);if(f)return f;}return ps[(i||0)%ps.length];}
function promoBtn(p,cls){return p.url?`<a class="${cls}" href="${esc(p.url)}" target="_blank" rel="noopener">${p.cta}</a>`:`<button class="${cls}" type="button" ${p.act==="chat"?'data-chat="1"':'data-promo="sub"'}>${p.cta}</button>`;}
