const PULSE_SYM={usd:"US$",gbp:"£",eur:"€"},PULSE_OFF=1;
const PULSE_TOP={nyc:1,sf:1,ldn:1},PULSE_MAJOR={atx:1,bos:1,la:1,mia:1,sgp:1,dxb:1,ber:1,par:1,ams:1,lis:1,mad:1,bcn:1};
const PULSE_GBP=["ldn","man","edi"],PULSE_EUR=["ams","bcn","ber","can","cph","dub","hel","lis","mil","muc","par","sto","zrh","dav","mad","osl","vie","prg","bru","waw","bud","iev","beg","ist"];
function pulseWeeks(start,n){return Array.from({length:n},(_,i)=>new Date(new Date(start+"T12:00:00Z").getTime()+i*7*864e5).toISOString().slice(0,10));}
function pulseTech(hub,monday){const e=new Date(new Date(monday+"T12:00:00Z").getTime()+6*864e5).toISOString().slice(0,10);return WEEKS.filter(w=>w.hub===hub&&w.start<=e&&w.end>=monday);}
const PULSE_IMG_SURCHARGE=0.35;   // graphic banner instead of a text headline: +35% overall, every currency and city. Keep in step with PULSE_IMG_SURCHARGE in yorkseed-backend listAds.routes.js.
function pulseCalc(hub,n,start,hasImage){const cur=PULSE_GBP.includes(hub)?"gbp":PULSE_EUR.includes(hub)?"eur":"usd",tier=PULSE_TOP[hub]?"top":PULSE_MAJOR[hub]?"major":"std",p=PULSE_PRICE[cur][tier];const base=Math.round((Math.floor(n/4)*p[1]+(n%4)*p[0])*PULSE_OFF);const wk=start?pulseWeeks(start,n):[];const tech=wk.filter(w=>pulseTech(hub,w).length);const names=[...new Set(tech.flatMap(w=>pulseTech(hub,w).map(x=>x.name)))];const withSurge=base+Math.round(base*0.3*tech.length/n);const amt=hasImage?Math.round(withSurge*(1+PULSE_IMG_SURCHARGE)):withSurge;return{cur,tier,base,surge:tech.length,names,amt};}
